mapper.select:
SELECT UD.DEPARTMENT_ID, U.ID AS USER_ID, U.FULL_NAME, U.EMAIL, R.CODE AS RANK_CODE FROM USER_DEPARTMENTS UD INNER JOIN USERS U ON U.ID = UD.USER_ID AND U.DELETED_AT IS NULL AND COALESCE(U.IS_ACTIVE, TRUE) = TRUE LEFT JOIN JOB_TITLES JT ON JT.ID = U.JOB_TITLE_ID AND JT.DELETED_AT IS NULL LEFT JOIN RANKS R ON R.ID = JT.RANK_ID AND R.DELETED_AT IS NULL WHERE UD.DEPARTMENT_ID IN
#{id}
ORDER BY UD.DEPARTMENT_ID, U.FULL_NAME

SELECT KA.DEPARTMENT_ID, KA.ID AS ASSIGNMENT_ID, KA.CYCLE_ID, KC.YEAR AS CYCLE_YEAR, KI.ID AS KPI_INFO_ID, KM.CODE AS KPI_CODE, KM.NAME AS KPI_NAME, KA.STATUS_CODE, KM.TYPE_CODE, COALESCE(KI.TARGET_VALUE, KA.TARGET_VALUE) AS TARGET_VALUE, KI.WEIGHT FROM KPI_ASSIGNMENTS KA INNER JOIN KPI_CYCLES KC ON KC.ID = KA.CYCLE_ID AND KC.DELETED_AT IS NULL INNER JOIN KPIS_INFORMATION KI ON KI.ID = KA.KPI_INFO_ID AND KI.CYCLE_ID = KA.CYCLE_ID AND KI.DELETED_AT IS NULL INNER JOIN KPI_MASTER KM ON KM.ID = KI.MASTER_KPI_ID AND KM.DELETED_AT IS NULL WHERE KA.DELETED_AT IS NULL AND KA.USER_ID IS NULL AND KA.DEPARTMENT_ID IS NOT NULL AND KC.YEAR = #{year} AND KA.DEPARTMENT_ID IN
#{id}
ORDER BY KA.DEPARTMENT_ID, KM.NAME

SELECT COUNT(*)
FROM USER_DEPARTMENTS
WHERE DEPARTMENT_ID = #{departmentId}
  AND USER_ID = #{userId}

SELECT COUNT(*)
FROM USER_DEPARTMENTS
WHERE USER_ID = #{userId}

mapper.delete:
DELETE FROM USER_DEPARTMENTS
WHERE DEPARTMENT_ID = #{departmentId}
  AND USER_ID = #{userId}

DELETE FROM USER_DEPARTMENTS
WHERE USER_ID = #{userId}
  AND DEPARTMENT_ID != #{keepDepartmentId}

mapper.select:
SELECT D.ID
FROM DEPARTMENTS D
WHERE D.DELETED_AT IS NULL
  AND D.MANAGER_ID = #{userId}
  AND D.ID != #{excludeDepartmentId}

mapper.update:
UPDATE USER_DEPARTMENTS
SET IS_PRIMARY = FALSE
WHERE USER_ID = #{userId}

UPDATE USER_DEPARTMENTS
SET IS_PRIMARY = #{isPrimary}
WHERE USER_ID = #{userId}
  AND DEPARTMENT_ID = #{departmentId}
